import { createHash, createPrivateKey, createPublicKey, generateKeyPairSync, randomBytes, randomUUID, sign, verify, } from 'node:crypto';
export function encodeBase64Url(value) {
    const buffer = typeof value === 'string' ? Buffer.from(value, 'utf8') : value;
    return buffer.toString('base64url');
}
export function decodeBase64Url(value) {
    return Buffer.from(value, 'base64url');
}
export function hashValue(value) {
    return createHash('sha256').update(value).digest('hex');
}
export function generateOpaqueToken(size = 32) {
    return randomBytes(size).toString('base64url');
}
export function generateEd25519KeyRecord() {
    const { privateKey, publicKey } = generateKeyPairSync('ed25519');
    const kid = randomUUID();
    const publicJwk = publicKey.export({ format: 'jwk' });
    const privateJwk = privateKey.export({ format: 'jwk' });
    return {
        id: randomUUID(),
        kid,
        alg: 'EdDSA',
        publicJwk: {
            ...publicJwk,
            alg: 'EdDSA',
            kid,
            kty: 'OKP',
            crv: 'Ed25519',
            use: 'sig',
        },
        privateJwk: {
            ...privateJwk,
            alg: 'EdDSA',
            kid,
            kty: 'OKP',
            crv: 'Ed25519',
            use: 'sig',
        },
    };
}
export function toPublicJwk(privateJwk) {
    return {
        alg: privateJwk.alg,
        crv: privateJwk.crv,
        kid: privateJwk.kid,
        kty: privateJwk.kty,
        use: privateJwk.use,
        x: privateJwk.x,
    };
}
export function signJwt(payload, privateJwk, kid = privateJwk.kid) {
    const encodedHeader = encodeBase64Url(JSON.stringify({ alg: 'EdDSA', kid, typ: 'JWT' }));
    const encodedPayload = encodeBase64Url(JSON.stringify(payload));
    const signingInput = `${encodedHeader}.${encodedPayload}`;
    const signature = sign(null, Buffer.from(signingInput, 'utf8'), createPrivateJwkKey(privateJwk));
    return `${signingInput}.${encodeBase64Url(signature)}`;
}
export function verifyJwt(token, publicJwk) {
    const segments = token.split('.');
    if (segments.length !== 3) {
        throw new Error('Invalid JWT format');
    }
    const [encodedHeader, encodedPayload, encodedSignature] = segments;
    const header = JSON.parse(decodeBase64Url(encodedHeader).toString('utf8'));
    validateJwtHeader(header);
    const signingInput = `${encodedHeader}.${encodedPayload}`;
    const signature = decodeBase64Url(encodedSignature);
    const verified = verify(null, Buffer.from(signingInput, 'utf8'), createPublicJwkKey(publicJwk), signature);
    if (!verified) {
        throw new Error('Invalid JWT signature');
    }
    const payload = JSON.parse(decodeBase64Url(encodedPayload).toString('utf8'));
    return { header, payload };
}
function validateJwtHeader(header) {
    if (header.alg !== 'EdDSA') {
        throw new Error('JWT header alg must be EdDSA');
    }
    if (header.typ !== 'JWT') {
        throw new Error('JWT header typ must be JWT');
    }
    if (!header.kid) {
        throw new Error('JWT missing kid');
    }
}
function createPrivateJwkKey(privateJwk) {
    return createPrivateKey({ format: 'jwk', key: privateJwk });
}
function createPublicJwkKey(publicJwk) {
    return createPublicKey({ format: 'jwk', key: publicJwk });
}
